package com.careflow.hospital.doctors; import jakarta.persistence.LockModeType;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;public interface DoctorRepository extends JpaRepository<Doctor,UUID>{boolean existsByUserId(UUID userId);Optional<Doctor> findByUserId(UUID userId);List<Doctor> findAllByDepartmentIdAndActiveTrueOrderByFullNameAsc(UUID departmentId);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select d from Doctor d where d.id=:id")Optional<Doctor> findByIdForUpdate(@Param("id")UUID id);}
